(* [comment removed for export] *)
Lemma pixobj_opix : forall C A A' m' md (pix : Z) (v : pixv) (cv : cmapv), Cok C -> W C A' m' md ->
  pixobj C A A' m' pix v cv -> pixfacts v cv ->
  opix C A' m' pix (p_w v) (p_h v) (p_d v) (p_cmap v) (p_data v) (c_arr cv) cv /\
  (forall q, ~ oblk pix (p_data v) (p_cmap v) (c_arr cv) q -> live A' q = live A q) /\
  (forall b, oblk pix (p_data v) (p_cmap v) (c_arr cv) b -> live A b = None /\ live A' b <> None).
