Lemma pixDestroy_opix_W : forall (fx : FPState) C A m md regs (s pp c w h d cd dt ad : Z) (cv : cmapv) (ret : word) (S : TSet),
  Cok C -> W C A m md ->
  getr regs 2 = Z_to_bv 64 s -> (s mod 16 = 0)%Z -> (c_top C - LSTK + 64 + ALLOC_STACK <= s)%Z -> (s <= c_top C)%Z ->
  getr regs 1 = ret -> ret_ok ret -> getr regs 4 = Z_to_bv 64 1278416 -> (pp mod 8 = 0)%Z ->
  getr regs 10 = Z_to_bv 64 pp -> (s <= pp)%Z -> (pp + 8 <= c_top C)%Z ->
  rdn SEGS m (Z_to_bv 64 pp) 8 = Some (Z_to_le_bytes 8 c) ->
  opix C A m c w h d cd dt ad cv ->
  (forall A' m' vm' regs', W C A' m' (with_vmmaps vm' md) -> cs_kept regs regs' ->
     (forall q, oblk c dt cd ad q -> live A' q = None) -> (forall q, ~ oblk c dt cd ad q -> live A' q = live A q) ->
     POSTM C A' (pp + 8) m m' -> rdn SEGS m' (Z_to_bv 64 pp) 8 = Some (Z_to_le_bytes 8 0) -> (forall a : word, (s <= u a < pp)%Z -> m' a = m a) ->
     roomtr A (m_vmmaps md) A' vm' 0 0 ->
     realizes SEGS (mkCfg (@mkst fx regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (@mkst fx regs (450456 : word) m al_rom) md) S.
Proof using P16 PINS.
  intros fx C A m md regs s pp c w h d cd dt ad cv ret S CK HW E2 Hal Hst Hs E1 Hret E4 Hpp E10 H1 H2 RD OP K.
  pose proof CK as [T1 T2 T3 T4 T5]. cbn [snd ll_img LLU16] in T5. pose proof LSTK_val as LV. pose proof (u64_range (c_sp0 C)) as RS. unfold ALLOC_STACK in Hst.
  destruct OP as [Z0 | (Hp4 & Hp64 & Hd4 & Hd64 & Npd & HOK & Hw & Hh & L0p & L0d & Lp & Ld & PX & OC)].
  - subst c.
    apply (pixDestroy_null_W C A m md regs s pp None ret S CK HW E2 Hal ltac:(lia) Hs E1 Hret E10
             ltac:(cbn [slotok]; split; lia) Hpp RD).
    intros m' r' HW' CS PM FR.
    assert (RD' : rdn SEGS m' (Z_to_bv 64 pp) 8 = Some (Z_to_le_bytes 8 0)).
    { rewrite <- RD. apply rdn_ext; change (Z.of_nat 8) with 8%Z; rewrite u_Z2bv by lia; [lia|]. intros x Hx. apply FR. lia. }
    rewrite <- (with_vmmaps_same md) in HW' |- *.
    apply (K A m' (m_vmmaps md) r' HW' CS).
    + intros q Hq. exfalso. exact (O23LeptFuzz.oblk_null _ _ _ _ Hq).
    + intros q _. reflexivity.
    + apply (POSTM_mono C A s (pp + 8) m m'); [lia | exact PM].
    + exact RD'.
    + intros a Ha. apply FR. lia.
    + apply roomtr_refl; lia.
  - assert (Hc0 : c <> 0%Z) by lia.
    pose proof (wpl_of_range w d ltac:(unfold hdr_ok in HOK; lia) (proj1 HOK)) as WR.
    assert (Rpos : (0 < 4 * (wpl_of w d * h))%Z) by (assert (0 < wpl_of w d * h)%Z by (apply Z.mul_pos_pos; lia); lia).
    assert (EA : cd <> 0%Z -> c_arr cv = ad) by (intros Hcd; destruct OC as [Z1 | (_ & _ & _ & Ear & _)]; [lia | exact Ear]).
    apply (pixDestroy_keep_W C A m md regs s pp c cd (4 * c_nalloc cv) (4 * (wpl_of w d * h)) (hdv w h d cd dt) cv ret S
             CK HW E2 Hal Hst H1 H2 E1 Hret E4 Hpp E10 RD PX eq_refl eq_refl eq_refl Lp L0p Ld L0d Rpos ltac:(cbn [p_data hdv]; lia)).
    + destruct OC as [Z1 | (Hcd & CM & COK & Ear & Hcd24 & Had1 & Had & L0c & L0a & Lc & La & Hna & N1 & N2 & N3 & N4 & N5)]; [left; exact Z1 | right].
      rewrite Ear. cbn [p_data hdv].
      refine (conj CM (conj Lc (conj La (conj L0c (conj L0a (conj N1 (conj N2 (conj N3 (conj _ (conj _ Hna)))))))))); lia.
    + intros A' m' vm' r' HW' CS PD PM RD' FR RT.
      destruct PD as (P1 & P2 & P3 & P4).
      cbn [p_data p_cmap hdv] in P2, P3, P4.
      apply (K A' m' vm' r' HW' CS); [| | exact PM | exact RD' | exact FR | exact RT].
      * intros q (_ & [-> | [-> | (Hcd & [-> | ->])]]).
        -- exact P1.
        -- apply P2. lia.
        -- exact (proj1 (P3 Hcd)).
        -- rewrite <- (EA Hcd). exact (proj2 (P3 Hcd)).
      * intros q NQ. apply P4.
        -- intros ->. apply NQ. split; [exact Hc0 | left; reflexivity].
        -- intros _ ->. apply NQ. split; [exact Hc0 | right; left; reflexivity].
        -- intros Hcd. rewrite (EA Hcd). split; intros ->; apply NQ; split; try exact Hc0; right; right; split; try exact Hcd.
           ++ left; reflexivity.
           ++ right; reflexivity.
Qed.

