Definition SAVED3 (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : Prop :=
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 ret) /\ rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) /\
  rdn SEGS m (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)).
Lemma saved_keep : forall m m' s ret regs, SAVED3 m s ret regs -> (0 <= s - 24)%Z -> (s <= 2 ^ 64)%Z ->
  (forall a : word, (s - 24 <= u a < s)%Z -> m' a = m a) -> SAVED3 m' s ret regs.
Proof using Type.
  intros m m' s ret regs (S1 & S2 & S3) H0 H1 E.
  assert (R : forall k, (8 <= k <= 24)%Z -> rdn SEGS m' (Z_to_bv 64 (s - k)) 8 = rdn SEGS m (Z_to_bv 64 (s - k)) 8).
  { intros k Hk. apply rdn_ext; change (Z.of_nat 8) with 8%Z; rewrite u_Z2bv by lia; [lia|]. intros x Hx. apply E. lia. }
  unfold SAVED3. rewrite !R by lia. exact (conj S1 (conj S2 S3)).
Qed.
(* [comment removed for export] *)
Ltac sv_frm SV F Etop Evm := apply (saved_keep _ _ _ _ _ SV ltac:(lia) ltac:(lia)); intros a Ha; apply F;
  [ unfold heap_gap; rewrite Evm; lia
  | intros G; apply pin_glob in G; cbn in G; unfold inZ in G; cbn in G; lia
  | intros G; apply pin_errno in G; cbn in G; unfold inZ in G; cbn in G; lia
  | unfold hcell; cbn; lia
  | unfold scratch; rewrite Etop; lia ].
Ltac sv_out SV OUT := apply (saved_keep _ _ _ _ _ SV ltac:(lia) ltac:(lia)); intros a Ha; apply OUT; lia.

Lemma W_rinv_win : forall C A m m' md (lo n : Z), Cok C -> W C A m md -> rinv [(lo, n)] m m' ->
  (c_top C - LSTK <= lo)%Z -> (lo + n <= c_top C)%Z -> W C A m' md.
Proof.
  intros C A m m' md lo n CK HW RI H1 H2.
  apply (W_mod_local C A m m' md CK HW).
  - intros a NE. left. unfold win. destruct (Z_lt_ge_dec (u a) lo) as [L|L].
    + exfalso. apply NE. apply (O23LeptFuzz.rinv_out1 lo n m m' a RI). lia.
    + destruct (Z_lt_ge_dec (u a) (lo + n)) as [L'|L']; [lia|].
      exfalso. apply NE. apply (O23LeptFuzz.rinv_out1 lo n m m' a RI). lia.
  - exact (proj1 RI).
  - intros a Hx. destruct (Z_lt_ge_dec (u a) lo) as [L|L].
    + rewrite (O23LeptFuzz.rinv_out1 lo n m m' a RI) in Hx by lia. exact Hx.
    + destruct (Z_lt_ge_dec (u a) (lo + n)) as [L'|L'].
      * apply (w_win _ _ _ _ HW). unfold win. lia.
      * rewrite (O23LeptFuzz.rinv_out1 lo n m m' a RI) in Hx by lia. exact Hx.
Qed.

Lemma sub_al8 : forall s k, (s mod 16 = 0)%Z -> (k mod 8 = 0)%Z -> ((s - k) mod 8 = 0)%Z.
Proof.
  intros s k H1 H2. apply Zmod_divides in H1 as [c ->]; [|lia]. apply Zmod_divides in H2 as [e ->]; [|lia].
  replace (16 * c - 8 * e)%Z with ((2 * c - e) * 8)%Z by ring. apply Z_mod_mult.
Qed.

Lemma sub_al4 : forall s k, (s mod 16 = 0)%Z -> (k mod 4 = 0)%Z -> ((s - k) mod 4 = 0)%Z.
Proof.
  intros s k H1 H2. apply Zmod_divides in H1 as [c ->]; [|lia]. apply Zmod_divides in H2 as [e ->]; [|lia].
  replace (16 * c - 4 * e)%Z with ((4 * c - e) * 4)%Z by ring. apply Z_mod_mult.
Qed.

Lemma hdr_ok_111 : hdr_ok 1 1 1.
Proof.
  pose proof (wpl_of_range 1 1 ltac:(lia) ltac:(unfold dval; left; reflexivity)) as WR.
  unfold hdr_ok, dval. repeat split; [left; reflexivity | lia | lia | lia].
Qed.

