             CK HW7 X2 ltac:(rewrite <- Zminus_mod_idemp_l, Hsp16; reflexivity) ltac:(rewrite Etop; unfold ALLOC_STACK; rewrite LV; lia) ltac:(rewrite Etop; lia)
             X1 ltac:(red; apply bv_eq; reflexivity) T7 ltac:(apply sub_al8; [exact Hsp16 | reflexivity]) X10 ltac:(lia) ltac:(rewrite Etop; lia) R48' OPs7).
    intros A5 m5 vm5 r8 HW5' CS5 DEAD5 KEEP5 PM5 RD5 FR5 RT5. rewrite ?with_vmmaps_twice in HW5' |- *.
